#include "dsp/eq/EqDesign.h"
#include "dsp/effects/Delay.h"
#include "dsp/effects/Drive.h"
#include "dsp/effects/Echoes.h"
#include "dsp/effects/Crackle.h"
#include "dsp/effects/Glitch.h"
