        route (fanfare, "macro3", ParamIDs::fltEnv, 0.25f);
        route (fanfare, "modWheel", ParamIDs::osc (0, "VibAmount"), 0.15f);
        route (fanfare, "modWheel", ParamIDs::osc (1, "VibAmount"), 0.15f);
