        oneShot (tide, 0, { SP21 { 0.0f, 0.0f, 0.3f }, SP21 { 0.45f, 1.0f, 0.0f } });   // the hum opening into "ah"
        tide.set (ParamIDs::voiceVowel, 0.0f);
