        route (uprising, "modWheel", ParamIDs::fltCutoff, 0.15f);
        route (uprising, "macro1", ParamIDs::fltCutoff, 0.15f);
        route (uprising, "macro3", ParamIDs::shp (0, "Drive"), 0.4f);
        route (uprising, "macro3", ParamIDs::fltEnv, 0.2f);
