        constexpr std::array<float, 4> barLevels { 0.5f, 0.35f, 0.18f, 0.12f };
        for (int k = 0; k < 4; ++k)
            organ.osc (k, "On", 1.0f).osc (k, "Wave", sine).osc (k, "Transpose", bars[(size_t) k]).osc (k, "Volume", barLevels[(size_t) k])
                 .osc (k, "PhaseRand", 0.0f);
